#include <iostream>
#include <array>
#include <vector>
#include <span>
int sum(std::span<const int> values) {
    int result{};
    for (int value : values) { result += value; }
    return result;
}
int main() {
    std::array<int, 3> a{1, 2, 3};
    std::vector<int> v{4, 5};
    int raw[2]{6, 7};
    std::cout << sum(a) << ' ' << sum(v) << ' ' << sum(raw) << ' ' << sum(std::span<const int>{}) << '\n';
}

#include <iostream>
#include <vector>
int main() {
    std::vector<int> values;
    values.reserve(10);
    std::cout << values.size() << ' ' << (values.capacity() >= 10) << '\n';
    values.push_back(7);
    std::cout << values.size() << ' ' << values[0] << '\n';
}

